yakit.AutoInitYakit()
log.setLevel("info")
inputs = cli.String("inputs", cli.setRequired(true))
is_enable_ext = cli.Bool("is_enable_ext", cli.setRequired(true))
cli.check()
yakit.Info("is enable extend regex: %v", is_enable_ext)

result_maps = make(map[string]string, 0)

regx_maps = map[string]var{
    "ip":     `\d+\.\d+\.\d+\.\d+`,
    "domain": `(([a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,6})(:\d{1,5})?`,
    "phone":  `(13[0-9]|14[5|7]|15[^4]|17[6-9]|18[0-9])\\d{8}`,
    "mail":   `\w+([-+.]\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*`,
}

for _, line := range inputs.Split("\n") {
    for _, out_string := range re.ExtractIP(line){
        result_maps[out_string] = "ip"
    }
    for _, out_string := range re.ExtractEmail(line){
        result_maps[out_string] = "mail"
    }
    for _, out_string := range re.ExtractHostPort(line){
        result_maps[out_string] = "host:port"
    }
    for _, out_string := range re.ExtractPath(line){
        result_maps[out_string] = "path"
    }
    for _, out_string := range re.ExtractURL(line){
        result_maps[out_string] = "url"
    }
    if is_enable_ext {
        for r_type, r_regx := range regx_maps {
            for _, out_string := range re.FindAll(line, r_regx) {
                result_maps[out_string] = r_type
            }
        }
    }
}

yakit.EnableTable("result", ["data", "type"]) 
for data, d_type := range result_maps{
    table_datas = {
        "data": data,
        "type": d_type,
    }
    yakit.Info("match: %s, type: %s", data, d_type)
    yakit.TableData("result",  table_datas) 
}
